import{_ as a,o as s,c as t,ah as i}from"./chunks/framework.CNYUdSfs.js";const n="/projects/ArmPi_Pro/en/latest/assets/image1.DZO89uNP.png",o="/projects/ArmPi_Pro/en/latest/assets/image2.DHUZqMdu.png",r="data:image/png;base64,",l="/projects/ArmPi_Pro/en/latest/assets/image4.BqeTd1MO.png",h="data:image/png;base64,",p="/projects/ArmPi_Pro/en/latest/assets/image2.DHUZqMdu.png",c="data:image/png;base64,",d="/projects/ArmPi_Pro/en/latest/assets/image4.BqeTd1MO.png",m="/projects/ArmPi_Pro/en/latest/assets/image7.CgbewPCC.png",g="/projects/ArmPi_Pro/en/latest/assets/image8.DLrp95Y1.png",k="/projects/ArmPi_Pro/en/latest/assets/image9.BbTjOx6o.png",u="/projects/ArmPi_Pro/en/latest/assets/image10.BoI_oMCo.png",P=JSON.parse('{"title":"7. Monocular Camera Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12.monocular_camera.md","filePath":"docs/12.monocular_camera.md"}'),A={name:"docs/12.monocular_camera.md"};function b(y,e,E,f,v,C){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_7-monocular-camera-lesson" tabindex="-1">7. Monocular Camera Lesson <a class="header-anchor" href="#_7-monocular-camera-lesson" aria-label="Permalink to &quot;7. Monocular Camera Lesson&quot;">​</a></h1><h2 id="_7-1-monocular-camera-usage" tabindex="-1">7.1 Monocular Camera Usage <a class="header-anchor" href="#_7-1-monocular-camera-usage" aria-label="Permalink to &quot;7.1 Monocular Camera Usage&quot;">​</a></h2><p>ArmPi FPV is loaded with a USB monocular camera for obtaining camera image. The monocular camera has perception, panoramic, and monitoring functions. Compared with other types of cameras, it has advantages such as low latency, low jitter and plug-and-play capabilities. Furthermore, their compact and lightweight design, as well as high performance make monocular cameras a popular choice for industrial design.</p><p>This lesson will connect monocular camera to Raspberry Pi to explain the basic use of camera.</p><h3 id="_7-1-1-connect-camera" tabindex="-1">7.1.1 Connect Camera <a class="header-anchor" href="#_7-1-1-connect-camera" aria-label="Permalink to &quot;7.1.1 Connect Camera&quot;">​</a></h3><p>Connect monocular camera to any USB ports on Raspberry Pi board. It is recommended to connect to USB3.0 port (blue) for higher transmission rate, as shown in the picture below:</p><img loading="lazy" height="463" width="1269" src="'+n+'"><h3 id="_7-1-2-start-and-close-the-game" tabindex="-1">7.1.2 Start and Close the Game <a class="header-anchor" href="#_7-1-2-start-and-close-the-game" aria-label="Permalink to &quot;7.1.2 Start and Close the Game&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The entered command should be case sensitive, and &quot;<strong>Tab</strong>&quot; key can be used to complement key words.</p></section><p>(1) Power on the robot and use VNC Viewer to connect to the remote</p><img loading="lazy" height="713" width="1267" src="'+o+'"><p>(2) Click the left upper corner icon <img loading="lazy" height="29" width="31" src="'+r+'"> on the desktop to open the Terminator terminal.</p><img loading="lazy" height="614" width="980" class="common_img" src="'+l+'"><p>(3) Enter command and press Enter to close the APP auto-start service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.stop_ros.sh</span></span></code></pre></div><p>(4) Enter command and press Enter to turn on camera program file path.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/ubuntu/course/vision_course/</span></span></code></pre></div><p>(5) Enter command and press Enter to turn on camera.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> camera_display.py</span></span></code></pre></div><p>(6) If want to disable camera image, press &quot;<strong>Ctrl+C</strong>&quot; on terminal. Please try multiple times if fail to disable.</p><p>(7) Click the icon <img loading="lazy" height="34" width="42" src="'+h+`"> on the upper left corner of the desktop (Note: the command needs to be entered in the system path rather than in the Docker container to start the app service), and input command in the system path and press Enter to start APP service. Wait for the robotic arm to return to its initial position, and the buzzer will beep once.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_node.service</span></span></code></pre></div><h3 id="_7-1-3-project-outcome" tabindex="-1">7.1.3 Project Outcome <a class="header-anchor" href="#_7-1-3-project-outcome" aria-label="Permalink to &quot;7.1.3 Project Outcome&quot;">​</a></h3><p>After starting program, the camera image will display on screen.</p><h3 id="_7-1-4-program-parameter-analysis" tabindex="-1">7.1.4 Program Parameter Analysis <a class="header-anchor" href="#_7-1-4-program-parameter-analysis" aria-label="Permalink to &quot;7.1.4 Program Parameter Analysis&quot;">​</a></h3><p>The relevant source code of monocular camera is stored in ： <a href="../_static/source_code/camera_display.zip">/home/ubuntu/course/vision_course/camera_display.py</a></p><ul><li><strong>Read Camera</strong></li></ul><p>Read camera with the <code>VideoCapture()</code> function in cv2 library.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cv2.VideoCapture(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#读取摄像头(read camera)</span></span></code></pre></div><ul><li><strong>Read and Display Frame</strong></li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ret, frame </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cap.read()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ret:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        cv2.imshow(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;frame&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, frame)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cv2.waitKey(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 27</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            break</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        time.sleep(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.01</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Call read method to read camera image, and then call imshow method to display image. Take <code>cv2.imshow(&#39;frame&#39;, frame)</code> as example. The meaning of the augments in brackets is as follow.</p><p>The first argument <code>frame</code> denotes the title of the display frame.</p><p>The second argument <code>frame</code> is the camera image.</p><h2 id="_7-2-camera-calibration" tabindex="-1">7.2 Camera Calibration <a class="header-anchor" href="#_7-2-camera-calibration" aria-label="Permalink to &quot;7.2 Camera Calibration&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>before starting camera calibration, please print the chessboard picture in the same folder with this document in advance. To remain the smoothness of the picture, it is recommended to use a thick paper or fix the paper with heavy object.</p></section><p>Due to the irregular camera lens, the image captured will be affected by the lens causing distortion. In this circumstance, the image data obtained is not accurate enough so the camera needs to be calibrated manually to minimize the impact. Besides, the camera calibrate can also obtain the internal and external parameters of camera, which will be applied in image reconstruction of 3D scenes.</p><h3 id="_7-2-1-start-and-close-the-game" tabindex="-1">7.2.1 Start and Close the Game <a class="header-anchor" href="#_7-2-1-start-and-close-the-game" aria-label="Permalink to &quot;7.2.1 Start and Close the Game&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>the input command should be case sensitive, and keywords can be complemented by &quot;<strong>Tab</strong>&quot; key.</p></section><p>(1) Power on the robot and use VNC Viewer to connect to the remote desktop.</p><img loading="lazy" height="713" width="1267" src="`+p+'"><p>(2) Click the icon <img loading="lazy" height="29" width="31" src="'+c+'"> in the upper left corner of the desktop to open Terminator terminal.</p><img loading="lazy" height="614" width="980" src="'+d+'" class="common_img"><p>(3) Enter command and press Enter to close APP auto-start service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.stop_ros.sh</span></span></code></pre></div><p>(4) Input command and press Enter to open the camera calibration program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> armpi_fpv_bringup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> camera_calib.launch</span></span></code></pre></div><p>(5) After starting the calibration program, place the chessboard horizontally in front of the camera. Keep the chessboard in a horizontal position and quickly move and tilt the chessboard image in front of the camera. When multiple colored lines appear on the chessboard grid and the progress bar on the right side shows changes, it indicates that the calibration is in progress. During calibrating, you need to repeat this operation several times until the progress bar on the right side turns completely green.</p><img loading="lazy" height="692" width="1267" src="'+m+'"><p>In this case, the parameter &quot;<strong>x</strong>&quot; represents the left and right movements in the image field of view. We use it to shift the chessboard left or right. The parameter &quot;<strong>y</strong>&quot; represents the up and down movements in the image field of view. We use it to shift the chessboard up or down. The parameter &quot;<strong>size</strong>&quot; represents the orientation of the image and the distance from the camera. We use it to adjust the distance of the chessboard, either moving it closer or farther. The parameter &quot;<strong>Skew</strong>&quot; represents the degree of tilting in the image. We use it to randomly tilt the image at different angles when it is in a horizontal position.</p><p>(6) Until the progress bars of the parameters &quot;<strong>x</strong>&quot;, &quot;<strong>y</strong>&quot; and &quot;<strong>Skew</strong>&quot; turn green on the right, and the &quot;<strong>CALIBRATE</strong>&quot; icon is also displayed in green, it indicates that the calibration is complete, as as shown in the following figure</p><img loading="lazy" height="688" width="1269" src="'+g+'"><p>(7) Then click &quot;<strong>calibrate</strong>&quot; to start computing calibration.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>the duration of the calibration process is determined by the numbers of calibration images. The more images required, the longer the process will take.</p></section><p>(8) After calibration is complete, try to move the chessboard picture within the display to check if it is straight and click &quot;<strong>commit</strong>&quot;.</p><img loading="lazy" height="690" width="1265" src="'+k+'"><img loading="lazy" height="688" width="1267" src="'+u+'">',57)])])}const q=a(A,[["render",b]]);export{P as __pageData,q as default};
